(*----- Function qcp_rvv_read_lane -----*)

Definition qcp_rvv_read_lane_return_wit_1 := 
(
forall (i_pre: Z) (vl_pre: Z) (out_pre: Z) (p_pre: Z) (L: (@list fp32))  __default_fp32 (PreH1 : (i_pre < vl_pre)) (PreH2 : (0 <= vl_pre)) (PreH3 : (vl_pre <= 32)) (PreH4 : (0 <= i_pre)) (PreH5 : (i_pre < 32)) ,
  (((p_pre + (i_pre * sizeof(FLOAT)))) # Float  |-> (Znth i_pre L __default_fp32))
  **  (FloatArray.missing_i p_pre i_pre 0 vl_pre L )
  **  ((out_pre) # Float  |-> (Znth i_pre L __default_fp32))
|--
  (FloatArray.full p_pre vl_pre L )
  **  ((out_pre) # Float  |-> (rvv_read_value (i_pre) (vl_pre) (L)))
) \/
(
forall (i_pre: Z) (vl_pre: Z) (p_pre: Z) (L: (@list fp32))  __default_fp32 (PreH1 : (i_pre < vl_pre)) (PreH2 : (0 <= vl_pre)) (PreH3 : (vl_pre <= 32)) (PreH4 : (0 <= i_pre)) (PreH5 : (i_pre < 32)) ,
  (((p_pre + (i_pre * sizeof(FLOAT)))) # Float  |-> (Znth i_pre L __default_fp32))
  **  (FloatArray.missing_i p_pre i_pre 0 vl_pre L )
|--
  “ (fp32_eq (Znth i_pre L __default_fp32) (rvv_read_value (i_pre) (vl_pre) (L))) ”
  &&  (FloatArray.full p_pre vl_pre L )
).

