forall (i_pre: Z) (vl_pre: Z) (L: (@list fp32)) (PreH1 : (i_pre >= vl_pre)) (PreH2 : (0 <= vl_pre)) (PreH3 : (vl_pre <= 32)) (PreH4 : (0 <= i_pre)) (PreH5 : (i_pre < 32)) ,
